// Names respelled for a speech provider (data/pronunciation.json, the lexicon the narrators and Willo share). The
// spelling is only what the provider is sent, so the voice says the name right; the words anyone reads (captions, the
// story, the answer) keep the real one. Two lists, both generated by pipeline/lore/site_lore.py into
// site/public/lore/data/: respell.json for the narrators (a profile's story read aloud, lib/storyvoice.js), the
// lexicon's "qwen" spellings; respell-hosted.json for Willo's hosted voices (Inworld and DeepInfra, lib/companion-voice.js),
// its "hosted" spellings, else its "qwen" ones.

// Names respelled in `text`: longest first, whole words only, possessives kept. English only, like the spellings.
export function respell(text, names) {
  const list = Object.keys(names || {}).sort((a, b) => b.length - a.length);
  if (!list.length) return text;
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`(?<![\\p{L}\\p{N}_'’])(${list.map(esc).join("|")})(?![\\p{L}\\p{N}_])`, "gu");
  return text.replace(re, m => names[m]);
}

// A list's {name: spelling} pairs, or null when `data` isn't one (a missing file is the site's home page, not a 404).
function pairs(data) {
  if (!data || typeof data !== "object" || Array.isArray(data)) return null;
  return Object.fromEntries(Object.entries(data).filter(([name, spelling]) => name && typeof spelling === "string" && spelling));
}

// One list, read from the deploy's static files once per isolate. {} without the files, a list that isn't one or an
// error, so a voice is then sent the text as written, and the next call tries again.
const lists = new WeakMap();
export async function loadRespell(env, origin, path) {
  const assets = env?.ASSETS;
  if (!assets) return {};
  let byPath = lists.get(assets);
  if (!byPath) lists.set(assets, byPath = new Map());
  if (byPath.has(path)) return byPath.get(path);
  try {
    const res = await assets.fetch(new URL(path, origin));
    const names = res.ok ? pairs(await res.json()) : null;
    if (names) {
      byPath.set(path, names);
      return names;
    }
  } catch (e) {}
  return {};
}
